@RestController
@RequestMapping("/v1/campaigns")
class CampaignController(private val repo: CampaignRepository) {
  @PostMapping
  @Transactional              // 方法正常返回提交，抛 RuntimeException 回滚
  fun create(@RequestBody req: CreateReq): Campaign =
    repo.save(Campaign(shopId = req.shopId, budgetCap = req.budgetCap))
}
